INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Datenintegration immer mit einem Import verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch Export oder Sync sein"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Import"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Datenimport?', 3, '[{"text": "Daten in System einbinden", "correct": true, "because": "Erweitert Funktionalität"}, {"text": "Code optimieren", "correct": false, "because": "Kein direkter Bezug"}, {"text": "UI verbessern", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formate nutze ich für Datenintegration?', 5, '[{"text": "CSV", "correct": true, "because": "Einfach und weit verbreitet"}, {"text": "JSON", "correct": true, "because": "Strukturiert und flexibel"}, {"text": "EXE", "correct": false, "because": "Kein Datenformat"}, {"text": "PNG", "correct": false, "because": "Bildformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenanpassung ist vor Import nötig. b) Sie erfolgt immer manuell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Automatisierung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) oft richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist meist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Datenintegration?', 4, '[{"text": "Datenformat", "correct": false, "because": "Muss kompatibel sein"}, {"text": "Datenqualität", "correct": false, "because": "Beeinflusst Ergebnis"}, {"text": "Farbschema", "correct": true, "because": "Kein Bezug zu Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Software Daten importieren kann?', 2, '[{"text": "Nein", "correct": true, "because": "Funktion nicht immer vorhanden"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für einen CSV-Import?', 3, '[{"text": "Skriptsprache", "correct": true, "because": "Flexibel und effizient"}, {"text": "Grafikeditor", "correct": false, "because": "Für Bilder"}, {"text": "Compiler", "correct": false, "because": "Für Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Datenintegration wichtig?', 5, '[{"text": "Datenmapping", "correct": true, "because": "Ordnet Felder zu"}, {"text": "Validierung", "correct": true, "because": "Sichert Konsistenz"}, {"text": "UI-Design", "correct": false, "because": "Kein Bezug"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenintegration braucht Planung. b) Sie ist immer automatisiert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Manuell möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Datenimport?', 4, '[{"text": "Datenquelle", "correct": false, "because": "Essenziell"}, {"text": "Mapping-Regeln", "correct": false, "because": "Strukturiert Daten"}, {"text": "3D-Modellierung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist XML für große Datenmengen ideal?', 2, '[{"text": "Nein", "correct": true, "because": "Speicherintensiv"}, {"text": "Ja", "correct": false, "because": "Besser für Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern einen sauberen Import?', 4, '[{"text": "Datenbereinigung", "correct": true, "because": "Entfernt Fehler"}, {"text": "Testlauf", "correct": true, "because": "Prüft Ergebnisse"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass CSV nur für Tabellen geeignet ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Tabellarisches Format"}, {"text": "Nein", "correct": false, "because": "Eingeschränkt nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datenanpassung?', 3, '[{"text": "Konsistenz sicherstellen", "correct": true, "because": "Vermeidet Fehler"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenintegration kann fehlschlagen. b) Sie ist immer schnell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Datenintegration?', 5, '[{"text": "Datenverfügbarkeit", "correct": true, "because": "Zugriff erleichtert"}, {"text": "Prozessautomatisierung", "correct": true, "because": "Effizienz steigt"}, {"text": "Codeverkürzung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Import unwichtig?', 3, '[{"text": "Datenstruktur", "correct": false, "because": "Muss passen"}, {"text": "Fehlerprotokoll", "correct": false, "because": "Hilft bei Problemen"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Datenbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ich Daten immer anpassen?', 3, '[{"text": "Nein", "correct": true, "because": "Falls kompatibel"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob JSON hierarchische Daten gut abbildet?', 2, '[{"text": "Ja", "correct": true, "because": "Unterstützt Verschachtelung"}, {"text": "Nein", "correct": false, "because": "Flexibles Format"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um Importfehler zu finden?', 4, '[{"text": "Log-Analyse", "correct": true, "because": "Zeigt Probleme"}, {"text": "UI-Überprüfung", "correct": false, "because": "Kein Bezug"}, {"text": "Code-Neuschreiben", "correct": false, "because": "Zu aufwendig"}]');
